/* From Uiverse.io by AmIt-DasIT - Tags: dark, shadow, radio, neumorphism */
.__UIV_SCOPE__ .radio-input .label input {
  display: none;
}

.__UIV_SCOPE__ .radio-input {
  display: flex;
  gap: 20px;
}

.__UIV_SCOPE__ .radio-input .label {
  display: flex;
}

.__UIV_SCOPE__ .radio-input .label .check {
  width: 30px;
  height: 30px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
  cursor: pointer;
  transition: 0.3s;
  border: 3px solid transparent;
  box-shadow: 3px 3px 6px rgba(0, 0, 0, 0.5),
   -1px -1px 4px rgba(255, 255, 255, 0.5);
}

.__UIV_SCOPE__ .radio-input .label input:checked + .check {
  box-shadow: 3px 3px 6px rgba(0, 0, 0, 0.5),
   -1px -1px 4px rgba(255, 255, 255, 0.5),
   inset 3px 3px 6px rgba(0, 0, 0, 0.5),
   inset -1px -1px 4px rgba(255, 255, 255, 0.5);
  transform: scale(1.1);
}
